SELECT O.O_ORDERKEY, COALESCE(O.O_COMMENT, LAST_VALUE(O.O_COMMENT IGNORE NULLS) OVER (PARTITION BY O.O_ORDERSTATUS ORDER BY O.O_ORDERKEY ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), FIRST_VALUE(O.O_COMMENT IGNORE NULLS) OVER (PARTITION BY O.O_ORDERSTATUS ORDER BY O.O_ORDERKEY ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING)) AS COMMENT_FILL FROM {{ ref('SRC', 'ORDERS') }} O